"use server";

import { authenticatedActionClient } from "@/lib/utils/action-client";
import { getSession } from "@/modules/auth/lib/session";
import { getUser } from "@/lib/user/service";
import { lookupAuthorizedOrganizationIds } from "@/lib/authzed/organization-membership";
import { prisma } from "@formbricks/database";

interface OrganizationMembership {
  organizationName: string;
  role: string;
}

interface DownloadMyDataResult {
  name: string;
  email: string;
  locale: string;
  notificationSettings: Record<string, unknown>;
  organizationMemberships: OrganizationMembership[];
}

const ZDownloadMyDataInput = {} as const;

export const downloadMyDataAction = authenticatedActionClient
  .inputSchema(ZDownloadMyDataInput)
  .action(async () => {
    const session = await getSession();
    if (!session?.user) {
      return { error: "Not authenticated" };
    }

    const user = await getUser(session.user.id);
    if (!user) {
      return { error: "User not found" };
    }

    const organizationIds = await lookupAuthorizedOrganizationIds({
      type: "user",
      id: session.user.id,
    });

    const memberships: OrganizationMembership[] = [];

    if (organizationIds.length > 0) {
      const organizations = await prisma.organization.findMany({
        where: {
          id: { in: organizationIds },
        },
        select: {
          id: true,
          name: true,
        },
      });

      const orgMap = new Map(organizations.map((org) => [org.id, org.name]));

      const membershipsRaw = await prisma.membership.findMany({
        where: {
          userId: session.user.id,
          organizationId: { in: organizationIds },
        },
        select: {
          organizationId: true,
          role: true,
        },
      });

      for (const m of membershipsRaw) {
        memberships.push({
          organizationName: orgMap.get(m.organizationId) ?? "",
          role: m.role,
        });
      }
    }

    const data: DownloadMyDataResult = {
      name: user.name,
      email: user.email,
      locale: user.locale,
      notificationSettings: user.notificationSettings,
      organizationMemberships: memberships,
    };

    return { data };
  });

import { useTranslation } from "react-i18next";
import { formatDateForDisplay } from "@/lib/utils/datetime";

interface AccountActivityProps {
  createdAt: Date;
  lastLoginAt: Date | null;
  locale: string;
}

export const AccountActivity = ({ createdAt, lastLoginAt, locale }: Readonly<AccountActivityProps>) => {
  const { t } = useTranslation();

  return (
    <div>
      <div className="mb-4 flex items-center gap-2">
        <span className="font-regular text-xs text-slate-700">{t("workspace.settings.profile.account_created")}:</span>
        <span className="text-sm text-slate-900">{formatDateForDisplay(createdAt, locale)}</span>
      </div>
      <div className="flex items-center gap-2">
        <span className="font-regular text-xs text-slate-700">{t("workspace.settings.profile.last_login")}:</span>
        <span className="text-sm text-slate-900">
          {lastLoginAt ? formatDateForDisplay(lastLoginAt, locale) : t("common.not_set")}
        </span>
      </div>
    </div>
  );
};

"use client";

import { useState, useTransition } from "react";
import { useTranslation } from "react-i18next";
import { downloadMyDataAction } from "../actions";
import { Button } from "@/modules/ui/components/button";

export const DownloadMyData = () => {
  const { t } = useTranslation();
  const [isPending, startTransition] = useTransition();

  const handleDownload = () => {
    startTransition(async () => {
      const result = await downloadMyDataAction();

      if (result.error || !result.data) {
        return;
      }

      const { name, email, locale, notificationSettings, organizationMemberships } = result.data;

      const data = {
        name,
        email,
        locale,
        notificationSettings,
        organizationMemberships,
      };

      const jsonString = JSON.stringify(data, null, 2);
      const blob = new Blob([jsonString], { type: "application/json" });
      const url = URL.createObjectURL(blob);
      const link = document.createElement("a");
      link.href = url;
      link.download = "formbricks-data.json";
      document.body.appendChild(link);
      link.click();
      document.body.removeChild(link);
      URL.revokeObjectURL(url);
    });
  };

  return (
    <Button variant="secondary" size="sm" onClick={handleDownload} disabled={isPending}>
      {isPending ? t("workspace.settings.profile.downloading") : t("workspace.settings.profile.download_my_data")}
    </Button>
  );
};

/**
 * /api/v3/action-classes - list a workspace's action classes (read-only).
 * Session cookie or x-api-key; scope by workspaceId only. Lets API/MCP clients discover the
 * action-class ids referenced by app-survey triggers (`distribution.triggers[].actionClassId`).
 */
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { ZV3WorkspaceListQuery } from "@/app/api/v3/lib/schemas";
import { listV3ActionClasses } from "./lib/operations";

export const GET = withV3ApiWrapper({
  auth: "both",
  schemas: {
    query: ZV3WorkspaceListQuery,
  },
  handler: async ({ authentication, parsedInput, requestId, instance }) => {
    return await listV3ActionClasses({
      workspaceId: parsedInput.query.workspaceId,
      limit: parsedInput.query.limit,
      cursor: parsedInput.query.cursor,
      authentication,
      requestId,
      instance,
    });
  },
});

/**
 * POST /api/v3/workflows/{workflowId}/enable — validate executability, snapshot an immutable
 * version, and move the workflow to enabled. Thin adapter delegating to @formbricks/workflows/server.
 */
import { ZWorkflowIdInput } from "@formbricks/workflows";
import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { buildWorkflowApiContext, workflowsHandlers } from "../../lib/context";

export const POST = withV3ApiWrapper({
  auth: "both",
  action: "updated",
  targetType: "workflow",
  schemas: { params: ZWorkflowIdInput },
  handler: async ({ parsedInput, authentication, auditLog, requestId, instance }) =>
    workflowsHandlers.enable({
      ctx: buildWorkflowApiContext(authentication, requestId, instance, auditLog),
      params: parsedInput.params,
    }),
});

import { type NextRequest } from "next/server";
import { z } from "zod";
import { logger } from "@formbricks/logger";
import { TooManyRequestsError } from "@formbricks/types/errors";
import { authenticateRequest } from "@/app/api/v1/auth";
import { reportApiError } from "@/app/lib/api/api-error-reporter";
import {
  type ConcurrencyLimiter,
  type TReleaseSlot,
  releaseWhenBodySettles,
} from "@/app/lib/api/concurrency-limiter";
import {
  DEFAULT_REQUEST_BODY_LIMIT_BYTES,
  RequestBodyTooLargeError,
  readRequestBodyWithLimit,
} from "@/app/lib/api/request-body";
import { withAuthorizationSurface } from "@/lib/authorization/context";
import { getApiKeyFromHeaders } from "@/modules/api/lib/api-key-auth";
import { getSession } from "@/modules/auth/lib/session";
import { applyRateLimit } from "@/modules/core/rate-limit/helpers";
import { rateLimitConfigs } from "@/modules/core/rate-limit/rate-limit-configs";
import type { TRateLimitConfig } from "@/modules/core/rate-limit/types/rate-limit";
import { TAuditAction, TAuditTarget } from "@/modules/ee/audit-logs/types/audit-log";
import {
  arrayBudgetInvalidParam,
  findArrayBudgetViolation,
  findRawArrayBudgetViolation,
} from "./array-budget";
import { buildV3AuditLog, queueV3AuditLog } from "./audit";
import { mapV3ThrownError } from "./errors";
import { BoundedInvalidParams } from "./invalid-params";
import {
  type InvalidParam,
  isInvalidParamCode,
  problemBadRequest,
  problemCapacityReached,
  problemConcurrencyLimitReached,
  problemPayloadTooLarge,
  problemTooManyRequests,
  problemUnauthorized,
  withBearerChallenge,
} from "./response";
import type { TV3AuditLog, TV3Authentication } from "./types";

type TV3Schema = z.ZodTypeAny;
type MaybePromise<T> = T | Promise<T>;

export type TV3AuthMode = "none" | "session" | "apiKey" | "both";

export type TV3Schemas = {
  body?: TV3Schema;
  query?: TV3Schema;
  params?: TV3Schema;
};

export type TV3ParsedInput<S extends TV3Schemas | undefined> = S extends object
  ? {
      [K in keyof S as NonNullable<S[K]> extends TV3Schema ? K : never]: z.infer<NonNullable<S[K]>>;
    }
  : Record<string, never>;

export type TV3HandlerParams<TParsedInput = Record<string, never>, TProps = unknown> = {
  req: NextRequest;
  props: TProps;
  authentication: TV3Authentication;
  auditLog?: TV3AuditLog;
  parsedInput: TParsedInput;
  requestId: string;
  instance: string;
};

export type TWithV3ApiWrapperParams<S extends TV3Schemas | undefined, TProps = unknown> = {
  auth?: TV3AuthMode;
  schemas?: S;
  rateLimit?: boolean;
  customRateLimitConfig?: TRateLimitConfig;
  /**
   * The largest request body this route reads, in bytes. Defaults to `DEFAULT_REQUEST_BODY_LIMIT_BYTES`
   * (2 MB). Applies to declared and undeclared bodies alike, and is enforced while reading, so a body
   * sent without a `Content-Length` header is cut off at the limit rather than buffered whole.
   *
   * Raise it only for a route that genuinely takes a file-sized body, and keep it below Next's
   * `proxyClientMaxBodySize` (`next.config.mjs`). The patched Next (`patches/next@16.4.1.patch`) no longer
   * clones bodies for the proxy, but without the patch Next truncates a longer body before this reader sees
   * it, so the caller would get a 400 for malformed JSON instead of a 413.
   */
  bodyLimitBytes?: number;
  /**
   * Caps how many requests to this route one server process handles at once; the next one gets a 503
   * `capacity_reached` with `Retry-After`. The slot is taken after authentication and rate limiting but
   * **before the body is read**, so it also bounds the memory spent parsing large bodies, and it is held
   * until the response body is fully sent or cancelled, so a streamed response keeps its slot for as
   * long as it runs, or until the client disconnects. Share one `ConcurrencyLimiter` per route, created at
   * module scope.
   *
   * With `maxPerKey` on the limiter, one caller (session user or API key) can hold only that many slots;
   * the next of theirs gets a 429 with `Retry-After` instead.
   *
   * Rate limiting runs first on purpose, so a rate-limited caller never holds a slot; the price is that
   * a refusal still spends one rate-limit token.
   */
  concurrency?: { limiter: ConcurrencyLimiter; retryAfterSeconds: number };
  action?: TAuditAction;
  targetType?: TAuditTarget;
  handler: (params: TV3HandlerParams<TV3ParsedInput<S>, TProps>) => MaybePromise<Response>;
};

/** What the input-parsing steps need from the request beyond the request itself. */
type TV3ParseContext = {
  requestId: string;
  instance: string;
  bodyLimitBytes: number;
};

function getUnauthenticatedDetail(authMode: TV3AuthMode): string {
  if (authMode === "session") {
    return "Session required";
  }

  if (authMode === "apiKey") {
    return "API key required";
  }

  return "Not authenticated";
}

/** How many unknown keys a 400 will name before it stops enumerating them. */
const MAX_REPORTED_UNKNOWN_KEYS = 20;

function isPlainObject(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

/**
 * Expand a strict object's single unrecognized-keys issue into one param per offending key.
 *
 * Zod reports every unknown key in ONE issue whose path points at the object rather than at any of
 * the keys, so left as-is a caller is told it sent something unsupported without being told what.
 * Bounded, because the key list is caller-controlled and both the response and the log line carry it.
 */
function expandUnrecognizedKeys(issue: z.core.$ZodIssue, fallbackName: string): InvalidParam[] {
  const prefix = issue.path.length > 0 ? `${issue.path.join(".")}.` : "";
  // Read defensively rather than through the `code` narrowing: `error.issues` is typed as the base
  // `$ZodIssue`, which does not discriminate on `code`, so `issue.keys` is not reachable through it
  // even though the runtime value carries it.
  const rawKeys = (issue as { keys?: unknown }).keys;
  const unknownKeys = Array.isArray(rawKeys) ? rawKeys.map(String) : [];

  if (unknownKeys.length === 0) {
    // An empty list would silently drop the issue, leaving a 400 with no `invalid_params` at all.
    return [{ name: fallbackName, reason: issue.message, code: "unsupported_field" }];
  }

  const named = unknownKeys.slice(0, MAX_REPORTED_UNKNOWN_KEYS);
  const params: InvalidParam[] = named.map((key) => ({
    name: `${prefix}${key}`,
    reason: `Unsupported field '${key}'`,
    code: "unsupported_field",
  }));

  if (unknownKeys.length > named.length) {
    params.push({
      name: prefix ? prefix.slice(0, -1) : fallbackName,
      reason: `${unknownKeys.length - named.length} further unsupported fields were not listed`,
      code: "unsupported_field",
    });
  }

  return params;
}

/**
 * Zod issues as `invalid_params`, with the unknown-key expansion the v3 400 contract needs.
 *
 * Exported because `POST /api/v3/responses/validate` reports problems *inside* its payload as a 200
 * body rather than a 400, and those params have to be the ones the real write would have produced —
 * a second formatter would let the dry run describe the same rejection differently.
 *
 * Bounded to `V3_INVALID_PARAMS_MAX` entries plus a summary: the issue list is caller-shaped (one per
 * offending array element, one per unknown key), so an unbounded list is a response amplifier.
 */
export function formatZodIssues(error: z.ZodError, fallbackName: string): InvalidParam[] {
  const invalidParams = new BoundedInvalidParams();

  for (const issue of error.issues) {
    if (issue.code === "unrecognized_keys") {
      // Pushed one by one so the cap counts keys, not issues; the expansion is itself bounded.
      for (const param of expandUnrecognizedKeys(issue, fallbackName)) {
        invalidParams.push(() => param);
      }
      continue;
    }

    invalidParams.push(() => {
      const params = "params" in issue && isPlainObject(issue.params) ? issue.params : {};
      const code = isInvalidParamCode(params.code) ? params.code : undefined;

      return {
        name: issue.path.length > 0 ? issue.path.join(".") : fallbackName,
        reason: issue.message,
        ...(code ? { code } : {}),
      };
    });
  }

  return invalidParams.report(fallbackName, "request");
}

type TV3InputParseFailure = {
  ok: false;
  response: Response;
  detail: string;
  invalidParams: InvalidParam[];
};

function searchParamsToObject(searchParams: URLSearchParams): Record<string, string | string[]> {
  const query: Record<string, string | string[]> = {};

  for (const key of new Set(searchParams.keys())) {
    const values = searchParams.getAll(key);
    query[key] = values.length > 1 ? values : (values[0] ?? "");
  }

  return query;
}

function getRateLimitIdentifier(authentication: TV3Authentication): string | null {
  if (!authentication) {
    return null;
  }

  if ("user" in authentication && authentication.user?.id) {
    return authentication.user.id;
  }

  if ("apiKeyId" in authentication) {
    return authentication.apiKeyId;
  }

  return null;
}

function isPromiseLike<T>(value: unknown): value is Promise<T> {
  return typeof value === "object" && value !== null && "then" in value;
}

async function getRouteParams<TProps>(props: TProps): Promise<Record<string, unknown>> {
  if (!props || typeof props !== "object" || !("params" in props)) {
    return {};
  }

  const params = (props as { params?: unknown }).params;
  if (!params) {
    return {};
  }

  const resolvedParams = isPromiseLike<Record<string, unknown>>(params) ? await params : params;
  return typeof resolvedParams === "object" && resolvedParams !== null
    ? (resolvedParams as Record<string, unknown>)
    : {};
}

async function authenticateV3Request(req: NextRequest, authMode: TV3AuthMode): Promise<TV3Authentication> {
  if (authMode === "none") {
    return null;
  }

  if (authMode === "both" && getApiKeyFromHeaders(req.headers)) {
    return await authenticateRequest(req);
  }

  if (authMode === "session" || authMode === "both") {
    const session = await getSession();
    if (session?.user?.id) {
      return session;
    }

    if (authMode === "session") {
      return null;
    }
  }

  if (authMode === "apiKey" || authMode === "both") {
    return await authenticateRequest(req);
  }

  return null;
}

function invalidBodyFailure(
  invalidParams: InvalidParam[],
  requestId: string,
  instance: string
): TV3InputParseFailure {
  return {
    ok: false,
    detail: "Invalid request body",
    invalidParams,
    response: problemBadRequest(requestId, "Invalid request body", {
      instance,
      invalid_params: invalidParams,
    }),
  };
}

function bodyTooLargeFailure(
  error: RequestBodyTooLargeError,
  requestId: string,
  instance: string
): TV3InputParseFailure {
  return {
    ok: false,
    detail: error.message,
    invalidParams: [],
    response: problemPayloadTooLarge(requestId, error.message, instance),
  };
}

/**
 * The array budget, checked before any schema sees the body: an oversized array would otherwise cost
 * one Zod issue per element (ENG-3384), and this covers arrays a schema types as `unknown` or
 * `z.record` too. `readV3JsonBody` already held the raw text to the same budget, so this walk is the
 * second line: it sees the parsed value, which drops a repeated key's earlier values.
 */
function arrayBudgetFailure(
  bodyData: unknown,
  requestId: string,
  instance: string
): TV3InputParseFailure | null {
  const violation = findArrayBudgetViolation(bodyData);
  return violation
    ? invalidBodyFailure([arrayBudgetInvalidParam(violation, "body")], requestId, instance)
    : null;
}

type TV3JsonBodyRead =
  | { kind: "parsed"; data: unknown }
  | { kind: "malformed" }
  | { kind: "refused"; failure: TV3InputParseFailure };

/**
 * Read the body within the byte limit and hold it to the array budget on its raw text, before
 * `JSON.parse` builds a single object. Parsing is where a hostile body costs memory — 15.5 MiB of
 * `[[[…]]]` is ~470 MB of arrays — so on a route that takes bodies that large the budget has to hold
 * before the parse, not after it (ENG-3653).
 */
async function readV3JsonBody(
  req: Request,
  { requestId, instance, bodyLimitBytes }: TV3ParseContext
): Promise<TV3JsonBodyRead> {
  let text: string;
  try {
    text = await readRequestBodyWithLimit(req, bodyLimitBytes);
  } catch (error) {
    return error instanceof RequestBodyTooLargeError
      ? { kind: "refused", failure: bodyTooLargeFailure(error, requestId, instance) }
      : { kind: "malformed" };
  }

  const violation = findRawArrayBudgetViolation(text);
  if (violation) {
    return {
      kind: "refused",
      failure: invalidBodyFailure([arrayBudgetInvalidParam(violation, "body")], requestId, instance),
    };
  }

  try {
    return { kind: "parsed", data: JSON.parse(text) as unknown };
  } catch {
    return { kind: "malformed" };
  }
}

/** The body step of `parseV3Input`: read within the byte limit, check the array budget, then parse. */
async function parseV3Body(
  req: NextRequest,
  schema: TV3Schema,
  context: TV3ParseContext
): Promise<{ ok: true; body: unknown } | TV3InputParseFailure> {
  const { requestId, instance } = context;
  const read = await readV3JsonBody(req, context);
  if (read.kind === "refused") {
    return read.failure;
  }
  if (read.kind === "malformed") {
    return invalidBodyFailure(
      [{ name: "body", reason: "Malformed JSON input, please check your request body" }],
      requestId,
      instance
    );
  }

  const bodyData = read.data;
  const budgetFailure = arrayBudgetFailure(bodyData, requestId, instance);
  if (budgetFailure) {
    return budgetFailure;
  }

  const bodyResult = schema.safeParse(bodyData);
  if (!bodyResult.success) {
    return invalidBodyFailure(formatZodIssues(bodyResult.error, "body"), requestId, instance);
  }

  return { ok: true, body: bodyResult.data };
}

/**
 * The same byte limit and array budget for a route that declares no body schema but hands `req` to a
 * handler that reads it — the workflows family delegates its bodies to `packages/workflows`, whose
 * reader buffers the whole body before it measures it and answers 400 rather than 413. The checks run
 * on a clone so the handler's own stream stays intact; a body that is not JSON is left to the handler,
 * which owns that error.
 */
async function preflightUndeclaredBody(
  req: NextRequest,
  context: TV3ParseContext
): Promise<TV3InputParseFailure | null> {
  if (req.method === "GET" || req.method === "HEAD" || req.body === null) {
    return null;
  }

  const read = await readV3JsonBody(req.clone(), context);
  if (read.kind === "refused") {
    return read.failure;
  }
  if (read.kind === "malformed") {
    return null;
  }

  return arrayBudgetFailure(read.data, context.requestId, context.instance);
}

async function parseV3Input<S extends TV3Schemas | undefined, TProps>(
  req: NextRequest,
  props: TProps,
  schemas: S | undefined,
  context: TV3ParseContext
): Promise<{ ok: true; parsedInput: TV3ParsedInput<S> } | TV3InputParseFailure> {
  const { requestId, instance } = context;
  const parsedInput = {} as TV3ParsedInput<S>;

  if (schemas?.body) {
    const bodyResult = await parseV3Body(req, schemas.body, context);
    if (!bodyResult.ok) {
      return bodyResult;
    }

    parsedInput.body = bodyResult.body as TV3ParsedInput<S>["body"];
  } else {
    const preflightFailure = await preflightUndeclaredBody(req, context);
    if (preflightFailure) {
      return preflightFailure;
    }
  }

  if (schemas?.query) {
    const queryResult = schemas.query.safeParse(searchParamsToObject(req.nextUrl.searchParams));
    if (!queryResult.success) {
      const invalidParams = formatZodIssues(queryResult.error, "query");
      return {
        ok: false,
        detail: "Invalid query parameters",
        invalidParams,
        response: problemBadRequest(requestId, "Invalid query parameters", {
          instance,
          invalid_params: invalidParams,
        }),
      };
    }

    parsedInput.query = queryResult.data as TV3ParsedInput<S>["query"];
  }

  if (schemas?.params) {
    const paramsResult = schemas.params.safeParse(await getRouteParams(props));
    if (!paramsResult.success) {
      const invalidParams = formatZodIssues(paramsResult.error, "params");
      return {
        ok: false,
        detail: "Invalid route parameters",
        invalidParams,
        response: problemBadRequest(requestId, "Invalid route parameters", {
          instance,
          invalid_params: invalidParams,
        }),
      };
    }

    parsedInput.params = paramsResult.data as TV3ParsedInput<S>["params"];
  }

  return { ok: true, parsedInput };
}

function ensureRequestIdHeader(response: Response, requestId: string): Response {
  if (response.headers.get("X-Request-Id")) {
    return response;
  }

  const headers = new Headers(response.headers);
  headers.set("X-Request-Id", requestId);

  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

async function authenticateV3RequestOrRespond(
  req: NextRequest,
  authMode: TV3AuthMode,
  requestId: string,
  instance: string
): Promise<
  { authentication: TV3Authentication; response: null } | { authentication: null; response: Response }
> {
  const authentication = await authenticateV3Request(req, authMode);

  if (!authentication && authMode !== "none") {
    const unauthorized = problemUnauthorized(requestId, getUnauthenticatedDetail(authMode), instance);
    return {
      authentication: null,
      // RFC 9110 §15.5.2 wants a challenge *applicable to the target resource*. A "session" route accepts
      // no HTTP authentication scheme at all — cookies are not one — so there is none to send, and
      // advertising Bearer would tell a caller to try a credential this route never consults (see the
      // `authMode === "session"` early return above). The other modes do accept `Authorization: Bearer`.
      response: authMode === "session" ? unauthorized : withBearerChallenge(unauthorized),
    };
  }

  return {
    authentication,
    response: null,
  };
}

async function applyV3RateLimitOrRespond(params: {
  authentication: TV3Authentication;
  enabled: boolean;
  config: TRateLimitConfig;
  requestId: string;
  log: ReturnType<typeof logger.withContext>;
}): Promise<Response | null> {
  const { authentication, enabled, config, requestId, log } = params;
  if (!enabled) {
    return null;
  }

  const identifier = getRateLimitIdentifier(authentication);
  if (!identifier) {
    return null;
  }

  try {
    await applyRateLimit(config, identifier);
  } catch (error) {
    log.warn({ err: error, statusCode: 429 }, "V3 API rate limit exceeded");
    return problemTooManyRequests(
      requestId,
      error instanceof Error ? error.message : "Rate limit exceeded",
      error instanceof TooManyRequestsError ? error.retryAfter : undefined
    );
  }

  return null;
}

/**
 * Report a 5xx to the logs and to Sentry, through the same reporter v1 already uses.
 *
 * There was no error reporting under `app/api/v3` at all before this — the surface MCP agents and the
 * SDK consume was the one with no signal when it broke. `reportApiError` is reused rather than calling
 * `Sentry.captureException` here: it already owns the gating (`SENTRY_DSN && IS_PRODUCTION`), the
 * correlation id, the safe error serialization, and the rule that a reporter failure can never affect
 * the response.
 *
 * Called on both exits, because a v3 500 usually is not thrown. Operations return a problem response
 * rather than throwing — they have to, since the MCP server calls them directly with no wrapper — so
 * reporting only from the `catch` would miss almost every real failure. The thrown path additionally
 * passes the original error, which is what gives Sentry a stack rather than a synthetic one.
 *
 * `apiVersion` is passed explicitly instead of being derived from the path: under a `basePath`
 * deployment the request URL is prefixed, and the reporter's own matcher would fall back to "unknown".
 *
 * 503 is excluded. In v3 it is a deployment state, not a fault: `problemServiceUnavailable` means "this
 * capability is not enabled here", and a transient outage is a 502 (`response.ts`), which still reports.
 * So every 503 is an operator configuration answer — a self-hoster with a Sentry DSN and no Hub or AI
 * key would otherwise raise an `error`-level event on every such request, forever, for a deployment
 * that is behaving exactly as configured. Downgrading instead of skipping is not an option worth taking:
 * `buildSentryCaptureContext` hardcodes `level: "error"` for v1 and v2 as well, so a severity knob
 * belongs to the shared reporter, not to this wrapper. Nothing is lost locally either — the Hub paths
 * that produce most 503s already log at `warn` with a hint in `@/modules/hub/service`.
 */
const reportServerError = (req: NextRequest, response: Response, error?: unknown): void => {
  if (response.status < 500 || response.status === 503) {
    return;
  }

  try {
    reportApiError({ request: req, status: response.status, error, apiVersion: "v3" });
  } catch {
    // `reportApiError` already swallows its own failures, so this should be unreachable — but it is
    // called on the success return path, where an escaping throw would be caught by the wrapper's own
    // `catch` and rewrite the handler's status. A 502 becoming a 500 because Sentry hiccuped is the
    // exact class of thing observability must not do.
  }
};

/**
 * The answer to a request the route's concurrency limit turned away. Over the caller's own share it is
 * the caller sending too many (429); with every slot on the process taken it is this server being busy
 * (503 `capacity_reached`). Both carry `Retry-After`.
 */
function refuseOverConcurrency(
  reason: "capacity" | "per_key",
  concurrency: NonNullable<TWithV3ApiWrapperParams<undefined>["concurrency"]>,
  {
    requestId,
    instance,
    log,
  }: { requestId: string; instance: string; log: ReturnType<typeof logger.withContext> }
): Response {
  if (reason === "per_key") {
    log.warn(
      { statusCode: 429, maxPerKey: concurrency.limiter.maxPerKey },
      "V3 API caller is at its concurrency limit for this route"
    );
    return problemConcurrencyLimitReached(requestId, concurrency.retryAfterSeconds, instance);
  }

  log.warn(
    { statusCode: 503, maxInFlight: concurrency.limiter.maxInFlight },
    "V3 API route is at its concurrency limit"
  );
  return problemCapacityReached(requestId, concurrency.retryAfterSeconds, instance);
}

export const withV3ApiWrapper = <S extends TV3Schemas | undefined, TProps = unknown>(
  params: TWithV3ApiWrapperParams<S, TProps>
): ((req: NextRequest, props: TProps) => Promise<Response>) => {
  const {
    auth = "both",
    schemas,
    rateLimit = true,
    customRateLimitConfig,
    bodyLimitBytes = DEFAULT_REQUEST_BODY_LIMIT_BYTES,
    concurrency,
    handler,
    action,
    targetType,
  } = params;

  // A misconfigured limit is a programming error in the route module, so fail when the module loads
  // rather than on the first request: NaN or a fraction would make every body "too large", and a zero
  // or negative limit would refuse every request with a body.
  if (!Number.isSafeInteger(bodyLimitBytes) || bodyLimitBytes <= 0) {
    throw new Error(`withV3ApiWrapper: bodyLimitBytes must be a positive integer, got ${bodyLimitBytes}`);
  }

  if (
    concurrency &&
    (!Number.isSafeInteger(concurrency.retryAfterSeconds) || concurrency.retryAfterSeconds <= 0)
  ) {
    throw new Error(
      `withV3ApiWrapper: concurrency.retryAfterSeconds must be a positive integer, got ${concurrency.retryAfterSeconds}`
    );
  }

  return async (req: NextRequest, props: TProps): Promise<Response> => {
    const requestId = req.headers.get("x-request-id") ?? crypto.randomUUID();
    const instance = req.nextUrl.pathname;
    const log = logger.withContext({
      requestId,
      method: req.method,
      path: instance,
    });
    let auditLog: TV3AuditLog | undefined;
    // Set while this request holds a concurrency slot. Every exit releases it in `finally`, except a
    // response with a body, which takes it over (see `releaseWhenBodySettles`).
    let releaseSlot: TReleaseSlot | undefined;

    try {
      const authResult = await authenticateV3RequestOrRespond(req, auth, requestId, instance);
      if (authResult.response) {
        log.warn(
          { statusCode: authResult.response.status, detail: getUnauthenticatedDetail(auth) },
          "V3 API authentication failed"
        );
        return authResult.response;
      }

      const rateLimitResponse = await applyV3RateLimitOrRespond({
        authentication: authResult.authentication,
        enabled: rateLimit,
        config: customRateLimitConfig ?? rateLimitConfigs.api.v3,
        requestId,
        log,
      });
      if (rateLimitResponse) {
        return rateLimitResponse;
      }

      if (concurrency) {
        const slot = concurrency.limiter.tryAcquire(
          getRateLimitIdentifier(authResult.authentication) ?? undefined
        );
        if (!slot.ok) {
          return refuseOverConcurrency(slot.reason, concurrency, { requestId, instance, log });
        }
        releaseSlot = slot.release;
      }

      const parsedInputResult = await parseV3Input(req, props, schemas, {
        requestId,
        instance,
        bodyLimitBytes,
      });
      if (!parsedInputResult.ok) {
        // The count and the first few names, never the array: it is as long as the caller made it,
        // and a `reason` can echo caller input (ENG-3384).
        log.warn(
          {
            statusCode: parsedInputResult.response.status,
            detail: parsedInputResult.detail,
            invalidParamCount: parsedInputResult.invalidParams.length,
            invalidParamNames: parsedInputResult.invalidParams.slice(0, 5).map((param) => param.name),
          },
          "V3 API request validation failed"
        );
        return parsedInputResult.response;
      }

      // Built after authentication, rate limiting and parsing on purpose (ENG-2872). A 401 has no actor
      // to attribute — and an unauthenticated caller could fill the audit store one row per bad key; a
      // 429 is already logged by the limiter; a 400 is a malformed request, not an authorization event.
      // The rejection a reviewer wants — the 403 an authenticated caller gets for someone else's
      // resource — is raised by the operation below and is audited as a failure. MCP's scope gate
      // audits its own refusals in `registerScopedTool`.
      auditLog = buildV3AuditLog(authResult.authentication, action, targetType, req.url);

      const execute = () =>
        handler({
          req,
          props,
          authentication: authResult.authentication,
          auditLog,
          parsedInput: parsedInputResult.parsedInput,
          requestId,
          instance,
        });
      const response = authResult.authentication
        ? await withAuthorizationSurface("api_v3", execute)
        : await execute();

      if (auditLog) {
        if (response.ok) {
          auditLog.status = "success";
        } else {
          auditLog.eventId = requestId;
        }
      }

      await queueV3AuditLog(auditLog, requestId, log);
      reportServerError(req, response);
      const finalResponse = ensureRequestIdHeader(response, requestId);

      if (!releaseSlot) {
        return finalResponse;
      }

      // From here the response body owns the slot, given back when it settles or the client leaves.
      // Handed over only once `releaseWhenBodySettles` has wrapped the body: if that throws, `finally`
      // still holds the slot to give back.
      const settling = releaseWhenBodySettles(finalResponse, releaseSlot, req.signal);
      releaseSlot = undefined;
      return settling;
    } catch (error) {
      if (auditLog) {
        auditLog.eventId = requestId;
        await queueV3AuditLog(auditLog, requestId, log);
      }
      // Defence in depth. Operations map their own throws and return a problem response — they have to,
      // because the MCP tools call them directly, without this wrapper. Anything reaching here escaped
      // that, so it is mapped by the same rules rather than being flattened into a blanket 500.
      const mapped = mapV3ThrownError(error, { log, requestId, instance });
      reportServerError(req, mapped, error);
      return ensureRequestIdHeader(mapped, requestId);
    } finally {
      releaseSlot?.();
    }
  };
};

"use client";

import { useQuery } from "@tanstack/react-query";
import { getTextContent } from "@formbricks/types/surveys/validation";
import { extractFallbackValue, extractId, extractRecallInfo } from "@/lib/utils/recall";
import { parseV3ApiError } from "@/modules/api/lib/v3-client";
import { initialFilters } from "@/modules/survey/list/lib/constants";
import { listSurveys } from "@/modules/survey/list/lib/v3-surveys-client";
import type { TOutboundSurvey } from "@/modules/survey/visibility/lib/outbound";

// Picker needs every survey, so walk the v3 cursor list until exhausted.
const SURVEY_LIST_PAGE_SIZE = 100;
// Ceiling so a runaway cursor can't spin forever; covers 2,000 surveys, then the picker truncates.
const SURVEY_LIST_MAX_PAGES = 20;

interface TWorkflowSurveyOption extends TOutboundSurvey {
  id: string;
  name: string;
}

interface TWorkflowSurveyEnding {
  id: string;
  label: string;
}

// The v3 survey endpoint serializes i18n strings as a language-keyed map (e.g.
// `headline = { "en-US": "Thanks!" }`), not the canonical `headline.default` shape — so read the
// value under the survey's `defaultLanguage` (falling back to any string), stripped to plain text.
interface RawEnding {
  id?: string;
  type?: unknown;
  headline?: Record<string, unknown>;
  label?: unknown;
}

const pickDefaultLanguageString = (value: unknown, defaultLanguage: string): string | null => {
  if (!value || typeof value !== "object") return null;
  const map = value as Record<string, unknown>;
  const direct = map[defaultLanguage];
  if (typeof direct === "string" && direct.trim()) return direct;
  for (const entry of Object.values(map)) {
    if (typeof entry === "string" && entry.trim()) return entry;
  }
  return null;
};

/**
 * What each recall-able id in the survey renders as: element headlines, variable names, and hidden
 * field ids — the same three sources `getRecallItemLabel` resolves against in the survey editor.
 * Built from the v3 payload rather than reusing `recallToHeadline`, which expects the canonical
 * `TSurvey` i18n shape (`headline.default`) and not the language-keyed map v3 serializes.
 */
type RecallLabels = Record<string, string>;

interface RawSurveyBody {
  defaultLanguage?: unknown;
  endings: unknown;
  blocks?: unknown;
  hiddenFields?: unknown;
  variables?: unknown;
}

/** The v3 payload is untyped at this point, so walk blocks → elements defensively. */
const rawElementsFromBlocks = (blocks: unknown): unknown[] =>
  (Array.isArray(blocks) ? blocks : []).flatMap((block) => {
    const elements = (block as { elements?: unknown } | null)?.elements;
    return Array.isArray(elements) ? elements : [];
  });

const collectElementLabels = (blocks: unknown, defaultLanguage: string): RecallLabels => {
  const labels: RecallLabels = {};
  for (const element of rawElementsFromBlocks(blocks)) {
    const { id, headline } = (element ?? {}) as { id?: unknown; headline?: unknown };
    if (typeof id !== "string" || !id) continue;
    const headlineText = pickDefaultLanguageString(headline, defaultLanguage);
    if (headlineText) labels[id] = getTextContent(headlineText);
  }
  return labels;
};

const collectVariableLabels = (variables: unknown): RecallLabels => {
  const labels: RecallLabels = {};
  for (const variable of Array.isArray(variables) ? variables : []) {
    const { id, name } = (variable ?? {}) as { id?: unknown; name?: unknown };
    if (typeof id === "string" && id && typeof name === "string") labels[id] = name;
  }
  return labels;
};

/** A hidden field recalls as its own id. */
const collectHiddenFieldLabels = (hiddenFields: unknown): RecallLabels => {
  const labels: RecallLabels = {};
  const fieldIds = (hiddenFields as { fieldIds?: unknown } | null | undefined)?.fieldIds;
  for (const fieldId of Array.isArray(fieldIds) ? fieldIds : []) {
    if (typeof fieldId === "string" && fieldId) labels[fieldId] = fieldId;
  }
  return labels;
};

const buildRecallLabels = (data: RawSurveyBody, defaultLanguage: string): RecallLabels => ({
  // Later spreads win, so the order spells out `getRecallItemLabel`'s precedence: a hidden field
  // beats an element, and an element beats a variable.
  ...collectVariableLabels(data.variables),
  ...collectElementLabels(data.blocks, defaultLanguage),
  ...collectHiddenFieldLabels(data.hiddenFields),
});

/**
 * Resolves `#recall:<id>/fallback:<text>#` tokens to the label the survey editor shows, prefixed
 * with `@` as the editor's own ending picker does. A token whose target no longer exists resolves to
 * its fallback text rather than leaking a raw cuid into the picker.
 */
const resolveRecall = (text: string, recallLabels: RecallLabels): string => {
  let resolved = text;
  while (resolved.includes("#recall:")) {
    const recallInfo = extractRecallInfo(resolved);
    if (!recallInfo) break;
    const recallItemId = extractId(recallInfo);
    if (!recallItemId) break;

    const label = recallLabels[recallItemId];
    let replacement: string;
    if (label === undefined) {
      replacement = extractFallbackValue(recallInfo).replaceAll("nbsp", " ");
    } else {
      // A recalled headline can itself recall. The editor blanks the inner token instead of
      // resolving it recursively, and blanking is also what keeps this loop terminating.
      let flattened = label;
      while (flattened.includes("#recall:")) {
        const nested = extractRecallInfo(flattened);
        if (!nested) break;
        flattened = flattened.replace(nested, "___");
      }
      replacement = `@${flattened}`;
    }
    // Replacer function, not a replacement string: `$&` and friends in a fallback or a headline
    // would otherwise splice part of the pattern back in.
    resolved = resolved.replace(recallInfo, () => replacement);
  }
  return resolved;
};

const endingDisplayLabel = (raw: RawEnding, defaultLanguage: string, recallLabels: RecallLabels): string => {
  const id = typeof raw.id === "string" ? raw.id : "";
  if (raw.type === "endScreen") {
    const headlineText = pickDefaultLanguageString(raw.headline, defaultLanguage);
    if (headlineText) {
      const stripped = getTextContent(resolveRecall(headlineText, recallLabels));
      if (stripped) return stripped;
    }
  } else if (raw.type === "redirectToUrl") {
    const label = typeof raw.label === "string" ? raw.label.trim() : "";
    if (label) return label;
  }
  return id;
};

const isEndingArray = (value: unknown): value is RawEnding[] =>
  Array.isArray(value) && value.every((entry) => entry && typeof entry === "object");

export const useWorkflowSurveyOptions = (workspaceId: string) => {
  const query = useQuery({
    queryKey: ["workflow-trigger", "surveys", workspaceId],
    queryFn: async ({ signal }) => {
      const options: TWorkflowSurveyOption[] = [];
      let cursor: string | null = null;
      let pages = 0;
      do {
        const page = await listSurveys({
          workspaceId,
          limit: SURVEY_LIST_PAGE_SIZE,
          cursor,
          filters: initialFilters,
          signal,
        });
        for (const survey of page.data) {
          // `visibility` lets the picker refuse a restricted survey (ENG-3395).
          options.push({ id: survey.id, name: survey.name, visibility: survey.visibility });
        }
        cursor = page.meta.nextCursor;
        pages += 1;
        if (pages >= SURVEY_LIST_MAX_PAGES && cursor) {
          console.warn(
            `Workflow trigger survey picker truncated at ${SURVEY_LIST_MAX_PAGES * SURVEY_LIST_PAGE_SIZE} surveys.`
          );
          break;
        }
      } while (cursor);
      return options;
    },
  });
  return { ...query, options: query.data ?? [] };
};

export const useWorkflowSurveyEndings = (surveyId: string | null | undefined) => {
  const query = useQuery({
    queryKey: ["workflow-trigger", "survey-endings", surveyId],
    enabled: Boolean(surveyId),
    queryFn: async ({ signal }): Promise<{ surveyId: string | null; endings: TWorkflowSurveyEnding[] }> => {
      // Unreachable (`enabled` gates on a truthy id); keeps the resolved id non-optional for callers.
      if (!surveyId) return { surveyId: null, endings: [] };

      const response = await fetch(`/api/v3/surveys/${surveyId}`, {
        method: "GET",
        cache: "no-store",
        signal,
      });
      if (!response.ok) {
        throw await parseV3ApiError(response);
      }
      const body = (await response.json()) as { data: RawSurveyBody };
      const defaultLanguage =
        typeof body.data.defaultLanguage === "string" && body.data.defaultLanguage.length > 0
          ? body.data.defaultLanguage
          : "default";
      // Throw on a malformed shape rather than returning an empty list: a "successful" empty result
      // is indistinguishable from "all endings deleted" and would trigger a destructive auto-prune.
      if (!isEndingArray(body.data.endings)) {
        throw new Error(`Unexpected survey endings response shape for survey ${surveyId}`);
      }
      const recallLabels = buildRecallLabels(body.data, defaultLanguage);
      const endings: TWorkflowSurveyEnding[] = body.data.endings
        .filter((raw): raw is RawEnding & { id: string } => typeof raw.id === "string" && raw.id.length > 0)
        .map((raw) => ({ id: raw.id, label: endingDisplayLabel(raw, defaultLanguage, recallLabels) }));
      return { surveyId, endings };
    },
  });
  return {
    ...query,
    endings: query.data?.endings ?? [],
    // The survey the cached endings belong to. Callers pruning stored ids must check it — reading a
    // previous survey's (or unsettled) response as the current one would delete a valid selection.
    resolvedSurveyId: query.data?.surveyId ?? null,
  };
};

import { withV3ApiWrapper } from "@/app/api/v3/lib/api-wrapper";
import { ZV3EmptyQuery } from "@/app/api/v3/lib/schemas";
import { ZV3ResponseValidationRequestBody } from "../lib/schemas";
import { validateV3Response } from "../lib/validate-operations";

/**
 * `POST /api/v3/responses/validate`.
 *
 * No `auditLog`: this endpoint writes nothing, so there is nothing to record. Mirrors
 * `app/api/v3/surveys/validate/route.ts`, down to the dual auth.
 */
export const POST = withV3ApiWrapper({
  auth: "both",
  schemas: {
    body: ZV3ResponseValidationRequestBody,
    query: ZV3EmptyQuery,
  },
  handler: async ({ parsedInput, authentication, requestId, instance }) => {
    return await validateV3Response({
      body: parsedInput.body,
      authentication,
      requestId,
      instance,
    });
  },
});

import { AuthenticationError } from "@formbricks/types/errors";
import { AccountActivity } from "@/app/(app)/account/settings/profile/components/AccountActivity";
import { AccountSecurity } from "@/app/(app)/workspaces/[workspaceId]/settings/account/profile/components/AccountSecurity";
import { DeleteAccount } from "@/app/(app)/workspaces/[workspaceId]/settings/account/profile/components/DeleteAccount";
import { DownloadMyData } from "@/app/(app)/account/settings/profile/components/DownloadMyData";
import { EditProfileDetailsForm } from "@/app/(app)/workspaces/[workspaceId]/settings/account/profile/components/EditProfileDetailsForm";
import { SettingsCard } from "@/app/(app)/workspaces/[workspaceId]/settings/components/SettingsCard";
import {
  EMAIL_VERIFICATION_DISABLED,
  ENTERPRISE_LICENSE_REQUEST_FORM_URL,
  IS_FORMBRICKS_CLOUD,
  PASSWORD_RESET_DISABLED,
} from "@/lib/constants";
import { getOrganizationsWhereUserIsSingleOwner } from "@/lib/organization/service";
import { getUser } from "@/lib/user/service";
import { getTranslate } from "@/lingodotdev/server";
import { requiresPasswordConfirmationForAccountDeletion } from "@/modules/account/lib/account-deletion-auth";
import { getSession } from "@/modules/auth/lib/session";
import { LiteLicenseTip } from "@/modules/ee/license-check/components/lite-license-tip";
import { getEnterpriseLicense } from "@/modules/ee/license-check/lib/license";
import { getIsMultiOrgEnabled, getIsTwoFactorAuthEnabled } from "@/modules/ee/license-check/lib/utils";
import { getSettingsLayoutData } from "@/modules/settings/lib/navigation-data";
import { getOrganizationBillingPath } from "@/modules/settings/lib/routes";
import { IdBadge } from "@/modules/ui/components/id-badge";
import { PageContentWrapper } from "@/modules/ui/components/page-content-wrapper";
import { PageHeader } from "@/modules/ui/components/page-header";
import { UpgradePrompt } from "@/modules/ui/components/upgrade-prompt";

const Page = async () => {
  const isTwoFactorAuthEnabled = await getIsTwoFactorAuthEnabled();
  const isMultiOrgEnabled = await getIsMultiOrgEnabled();
  const t = await getTranslate();
  const session = await getSession();
  if (!session?.user) {
    throw new AuthenticationError(t("common.not_authenticated"));
  }

  const organizationsWithSingleOwner = await getOrganizationsWhereUserIsSingleOwner(session.user.id);
  const user = await getUser(session.user.id);
  if (!user) {
    throw new AuthenticationError(t("common.not_authenticated"));
  }

  // Two-factor upgrade points at the user's organization billing page (org-scoped after the refactor).
  const layoutData = await getSettingsLayoutData(session.user.id);
  const billingUpgradeHref = layoutData
    ? getOrganizationBillingPath(layoutData.organization.id, IS_FORMBRICKS_CLOUD)
    : "/";

  const canUseTwoFactorAuth = isTwoFactorAuthEnabled || user.twoFactorEnabled;
  // Self-hosted without any license key: 2FA is part of the free Lite license, so offer that instead
  // of the paid upgrade.
  const showTwoFactorLiteLicenseTip =
    !canUseTwoFactorAuth && !IS_FORMBRICKS_CLOUD && (await getEnterpriseLicense()).status === "no-license";

  let securityContent: React.ReactNode;
  if (canUseTwoFactorAuth) {
    securityContent = <AccountSecurity user={user} />;
  } else if (showTwoFactorLiteLicenseTip) {
    securityContent = (
      <LiteLicenseTip
        feature="two_factor_auth"
        title={t("workspace.settings.profile.two_factor_authentication_lite_license_title")}
        description={t("common.lite_license_tip_description")}
      />
    );
  } else {
    securityContent = (
      <UpgradePrompt
        title={t("workspace.settings.profile.unlock_two_factor_authentication")}
        description={t("workspace.settings.profile.two_factor_authentication_description")}
        buttons={[
          {
            text: IS_FORMBRICKS_CLOUD ? t("common.upgrade_plan") : t("common.request_trial_license"),
            href: IS_FORMBRICKS_CLOUD ? billingUpgradeHref : ENTERPRISE_LICENSE_REQUEST_FORM_URL,
          },
          {
            text: t("common.learn_more"),
            href: IS_FORMBRICKS_CLOUD
              ? billingUpgradeHref
              : "https://formbricks.com/learn-more-self-hosting-license?utm_source=formbricks-app&utm_medium=webapp&utm_campaign=ee_lock_two_factor",
          },
        ]}
      />
    );
  }

  const isPasswordResetEnabled = !PASSWORD_RESET_DISABLED && user.identityProvider === "email";
  const requiresPasswordConfirmation = requiresPasswordConfirmationForAccountDeletion(user);

  return (
    <PageContentWrapper>
      <PageHeader pageTitle={t("common.profile")} />
      <div>
        <SettingsCard
          title={t("workspace.settings.profile.personal_information")}
          description={t("workspace.settings.profile.update_personal_info")}>
          <EditProfileDetailsForm
            user={user}
            emailVerificationDisabled={EMAIL_VERIFICATION_DISABLED}
            isPasswordResetEnabled={isPasswordResetEnabled}
          />
        </SettingsCard>
        <SettingsCard
          title={t("workspace.settings.profile.account_activity")}
          description={t("workspace.settings.profile.account_activity_description")}>
          <AccountActivity
            createdAt={user.createdAt}
            lastLoginAt={user.lastLoginAt}
            locale={user.locale}
          />
        </SettingsCard>
        {user.identityProvider === "email" && (
          <SettingsCard
            title={t("common.security")}
            description={t("workspace.settings.profile.security_description")}
            bodyVariant={showTwoFactorLiteLicenseTip ? "bleed" : "padded"}>
            {securityContent}
          </SettingsCard>
        )}

        <SettingsCard
          title={t("workspace.settings.profile.delete_account")}
          description={t("workspace.settings.profile.confirm_delete_account")}>
          <DeleteAccount
            session={session}
            IS_FORMBRICKS_CLOUD={IS_FORMBRICKS_CLOUD}
            user={user}
            organizationsWithSingleOwner={organizationsWithSingleOwner}
            isMultiOrgEnabled={isMultiOrgEnabled}
            requiresPasswordConfirmation={requiresPasswordConfirmation}
          />
        </SettingsCard>
        <SettingsCard
          title={t("workspace.settings.profile.download_my_data")}
          description={t("workspace.settings.profile.download_my_data_description")}>
          <DownloadMyData />
        </SettingsCard>
        <IdBadge id={user.id} label={t("common.profile_id")} variant="column" />
      </div>
    </PageContentWrapper>
  );
};

export default Page;

/**
 * V3 API response helpers — RFC 9457 Problem Details (application/problem+json)
 * and list envelope for success responses.
 */

const PROBLEM_JSON = "application/problem+json" as const;
const CACHE_NO_STORE = "private, no-store" as const;

/**
 * Authentication scheme advertised on a 401. RFC 9110 §15.5.2 requires "a WWW-Authenticate header field
 * containing at least one challenge **applicable to the target resource**" — the qualifier is the whole
 * point, so quote it in full: an inapplicable challenge does not satisfy the requirement, it just makes
 * a false statement about the endpoint.
 *
 * Bearer is applicable wherever this API accepts `Authorization: Bearer <fbk_…>`, which `api-key-auth.ts`
 * does — so on the `apiKey` and `both` auth modes, and nowhere else. RFC 6750 §3 requires at least one
 * auth-param, so the realm stays; a bare `Bearer` would be non-conformant.
 *
 * Deliberately NOT sent on `session` routes, and not by `problemUnauthorized` itself: cookies are not an
 * HTTP authentication scheme (they appear nowhere in the IANA HTTP Authentication Scheme Registry), so a
 * cookie-only endpoint has no applicable challenge and the MUST is unsatisfiable there. The repo's own
 * OpenAPI already concedes this by modelling the session as `type: apiKey, in: cookie` rather than
 * `type: http`. Omitting beats advertising a scheme the route will never honour.
 *
 * The MCP surface builds its own richer challenge (`resource_metadata` and `scope`, which its spec
 * MUSTs and its SDK parses) in `withOAuthChallenge` — see `@/modules/mcp/auth`.
 */
export const BEARER_CHALLENGE = 'Bearer realm="formbricks"' as const;

/** Attach the bearer challenge to a 401. Applied by the wrapper for the auth modes it is true of. */
export function withBearerChallenge(response: Response): Response {
  const headers = new Headers(response.headers);
  headers.set("WWW-Authenticate", BEARER_CHALLENGE);
  return new Response(response.body, {
    status: response.status,
    statusText: response.statusText,
    headers,
  });
}

/**
 * The `code` vocabulary of this API's problem responses: a stable, locale-independent discriminator that
 * clients switch on instead of parsing `detail` (see `parseV3ApiError` in `@/modules/api/lib/v3-client`
 * and `responseToMcpToolResult` in `@/modules/mcp/errors`).
 *
 * This list is the source of truth. `Problem.yml` in the OpenAPI spec publishes the same set, and
 * `problem-codes.test.ts` fails if the two drift — the spec used to be hand-maintained, with nothing
 * checking it against the emitters. Codes are additive: removing or renaming one is a breaking change
 * for every client that branches on it.
 *
 * `invalid_workflow_state` and `workflow_not_executable` are emitted only by `@formbricks/workflows`,
 * which mirrors this vocabulary rather than importing it (it is a leaf package, deliberately
 * dependency-free) and also emits five of the codes above; its own `WORKFLOW_PROBLEM_CODES` is held to
 * this set by a drift test on the same spec file. Named rather than counted: the array is kept sorted by
 * `problem-codes.test.ts`, so any positional claim falsifies itself on the next insertion.
 */
export const V3_PROBLEM_CODES = [
  "ai_features_not_enabled",
  "ai_generated_payload_invalid",
  "ai_instance_not_configured",
  "ai_output_too_long",
  "ai_provider_auth_failed",
  "ai_smart_tools_disabled",
  "bad_gateway",
  "bad_request",
  "chart_in_use",
  "conflict",
  "creatives_not_entitled",
  "custom_css_plan_required",
  "dashboards_plan_required",
  "forbidden",
  "internal_server_error",
  "invalid_workflow_state",
  "not_authenticated",
  "not_found",
  "payload_too_large",
  "projection_pending",
  "service_unavailable",
  "stored_survey_invalid",
  "survey_has_linked_creatives",
  "survey_not_workspace_visible",
  "too_many_requests",
  "unprocessable_content",
  "visibility_blocked_by_connections",
  "visibility_change_not_allowed",
  "visibility_not_enabled",
  "workflow_not_executable",
  "workspace_survey_limit_reached",
] as const;

export type V3ProblemCode = (typeof V3_PROBLEM_CODES)[number];

/**
 * Codes emitted only by internal routes (`app/api/internal` and the older `app/api/(internal)` group),
 * which reuse these RFC 9457 helpers but are session-only and carry no published contract.
 *
 * Kept apart from `V3_PROBLEM_CODES` rather than folded into it, because that list is held to
 * `Problem.yml` by exact equality in both directions: adding an internal code there would publish, to
 * every public client, a discriminator no public operation can ever return — which is the same defect
 * as an undocumented code, pointing the other way. `problem-codes.test.ts` asserts the two sets stay
 * disjoint and that none of these reaches the spec.
 */
export const INTERNAL_PROBLEM_CODES = [
  "attachment_export_empty",
  "attachment_export_too_large",
  "capacity_reached",
  "concurrency_limit_reached",
  "member_in_other_organizations",
  "retention_exemption_exists",
  "retention_exemption_not_active",
  "retention_export_too_large",
] as const;

export type InternalProblemCode = (typeof INTERNAL_PROBLEM_CODES)[number];

/**
 * What the shared helpers accept. A public v3 route should only ever pass a `V3ProblemCode`; the union
 * exists so an internal route can reuse the same helpers without widening the field back to `string`.
 */
export type ProblemCode = V3ProblemCode | InternalProblemCode;

const V3_PROBLEM_CODE_SET = new Set<V3ProblemCode>(V3_PROBLEM_CODES);

export function isV3ProblemCode(value: unknown): value is V3ProblemCode {
  return typeof value === "string" && V3_PROBLEM_CODE_SET.has(value as V3ProblemCode);
}

export const INVALID_PARAM_CODES = [
  "dangling_reference",
  "duplicate_identifier",
  "duplicate_locale",
  "forbidden_identifier",
  "immutable_identifier",
  "invalid_locale",
  "invalid_reference",
  "limit_exceeded",
  "misordered_reference",
  "missing_required_field",
  "missing_translation",
  "qsf_limit_exceeded",
  "qsf_not_recognized",
  "read_only_field",
  "unsupported_field",
  "unsupported_locale",
] as const;

export type InvalidParamCode = (typeof INVALID_PARAM_CODES)[number];

const INVALID_PARAM_CODE_SET = new Set<InvalidParamCode>(INVALID_PARAM_CODES);

export function isInvalidParamCode(value: unknown): value is InvalidParamCode {
  return typeof value === "string" && INVALID_PARAM_CODE_SET.has(value as InvalidParamCode);
}

export type InvalidParam = {
  name: string;
  reason: string;
  code?: InvalidParamCode;
  identifier?: string;
  referenceType?:
    | "block"
    | "element"
    | "ending"
    | "hiddenField"
    | "language"
    | "variable"
    | "variableName"
    | "recall";
  missingId?: string;
  firstUsedAt?: string;
  conflictsWith?: string;
};

export type ProblemExtension = {
  code?: ProblemCode;
  requestId: string;
  details?: Record<string, unknown>;
  invalid_params?: InvalidParam[];
};

export type ProblemBody = {
  type?: string;
  title: string;
  status: number;
  detail: string;
  instance?: string;
} & ProblemExtension;

function problemResponse(
  status: number,
  title: string,
  detail: string,
  requestId: string,
  options?: {
    type?: string;
    instance?: string;
    code?: ProblemCode;
    details?: Record<string, unknown>;
    invalid_params?: InvalidParam[];
    headers?: Record<string, string>;
  }
): Response {
  const body: ProblemBody = {
    title,
    status,
    detail,
    requestId,
    ...(options?.type && { type: options.type }),
    ...(options?.instance && { instance: options.instance }),
    ...(options?.code && { code: options.code }),
    ...(options?.details && { details: options.details }),
    ...(options?.invalid_params && { invalid_params: options.invalid_params }),
  };

  const headers: Record<string, string> = {
    "Content-Type": PROBLEM_JSON,
    "Cache-Control": CACHE_NO_STORE,
    "X-Request-Id": requestId,
    ...options?.headers,
  };

  return Response.json(body, { status, headers });
}

export function problemBadRequest(
  requestId: string,
  detail: string,
  options?: { invalid_params?: InvalidParam[]; instance?: string }
): Response {
  return problemResponse(400, "Bad Request", detail, requestId, {
    code: "bad_request",
    instance: options?.instance,
    invalid_params: options?.invalid_params,
  });
}

export function problemPayloadTooLarge(
  requestId: string,
  detail: string = "Payload Too Large",
  instance?: string
): Response {
  return problemResponse(413, "Payload Too Large", detail, requestId, {
    code: "payload_too_large",
    instance,
  });
}

export function problemUnauthorized(
  requestId: string,
  detail: string = "Not authenticated",
  instance?: string
): Response {
  return problemResponse(401, "Unauthorized", detail, requestId, {
    code: "not_authenticated",
    instance,
  });
}

export function problemForbidden(
  requestId: string,
  detail: string = "You are not authorized to access this resource",
  instance?: string
): Response {
  return problemResponse(403, "Forbidden", detail, requestId, {
    code: "forbidden",
    instance,
  });
}

/**
 * An AI capability the caller cannot use: 503 when this deployment has no AI configured at all, 403 when
 * it is configured but not enabled for the organization.
 *
 * `title` is the HTTP reason phrase for the status, not a description of the cause. RFC 9457 §4.2.1
 * requires that of a problem whose `type` is absent (and therefore `about:blank`), which is every v3
 * problem. The cause is carried by `code`, which is what clients branch on anyway — see
 * `getAiErrorMessage` in `@/modules/survey/components/template-list/lib/ai-error-messages`.
 */
export function problemAIUnavailable(
  requestId: string,
  detail: string,
  code: V3ProblemCode,
  instance?: string
): Response {
  const isNotConfigured = code === "ai_instance_not_configured";

  return problemResponse(
    isNotConfigured ? 503 : 403,
    isNotConfigured ? "Service Unavailable" : "Forbidden",
    detail,
    requestId,
    { code, instance }
  );
}

export function problemUnprocessableContent(
  requestId: string,
  detail: string,
  options?: { invalid_params?: InvalidParam[]; instance?: string; code?: ProblemCode }
): Response {
  return problemResponse(422, "Unprocessable Content", detail, requestId, {
    code: options?.code ?? "unprocessable_content",
    instance: options?.instance,
    invalid_params: options?.invalid_params,
  });
}

/**
 * ENG-2949: adding or editing custom CSS needs the Scale plan on Formbricks Cloud. Independent of the
 * resource, so it reveals nothing about it; removing CSS never answers this.
 */
export function problemCustomCssPlanRequired(requestId: string, detail: string, instance?: string): Response {
  return problemResponse(403, "Forbidden", detail, requestId, {
    code: "custom_css_plan_required",
    instance,
  });
}

/**
 * ENG-6584: charts and dashboards need the Dashboards add-on on Formbricks Cloud or a license that
 * includes it. Checked after authorization, so it reveals nothing to a caller without access, and
 * independent of any one resource.
 */
export function problemDashboardsPlanRequired(requestId: string, instance?: string): Response {
  return problemResponse(
    403,
    "Forbidden",
    "Dashboards are not enabled for this organization. They require the Dashboards add-on or an Enterprise license that includes it — an organization owner can enable them from the organization's billing or license settings.",
    requestId,
    { code: "dashboards_plan_required", instance }
  );
}

/**
 * ENG-6602: the instance's license doesn't include Creatives. In wind-down (the workspace still has
 * creatives) only reading them and taking them down stay allowed, and the detail says so; otherwise
 * every creatives operation answers this. Only ever answered after the caller's own access to the
 * workspace, so it reveals nothing about a workspace the caller can't see.
 */
export function problemCreativesNotEntitled(
  requestId: string,
  options: { windDown: boolean; instance?: string }
): Response {
  const detail = options.windDown
    ? "Creatives is not included in this instance's license: existing creatives can only be listed, read, paused, closed or deleted"
    : // Not "license": Formbricks Cloud has none, and Creatives isn't offered there.
      "Creatives is not available on this instance";

  return problemResponse(403, "Forbidden", detail, requestId, {
    code: "creatives_not_entitled",
    instance: options.instance,
  });
}

/**
 * ENG-3641: custom CSS that the processor rejected (syntax, size or complexity limits, processing
 * failure). A 422 like any other semantic document failure; `details.errors` carries the processor's
 * located errors (code, scope, appearance, line, column, reason), `invalid_params` the same as fields.
 */
export function problemCustomCssInvalid(
  requestId: string,
  options: { invalid_params: InvalidParam[]; errors: unknown[]; instance?: string }
): Response {
  return problemResponse(422, "Unprocessable Content", "Custom CSS failed validation", requestId, {
    code: "unprocessable_content",
    instance: options.instance,
    invalid_params: options.invalid_params,
    details: { errors: options.errors },
  });
}

/**
 * ENG-3282: survey visibility is not available here — the organization lacks the entitlement or the
 * deployment's readiness marker is unset (contract §5). Independent of the survey, so it reveals
 * nothing about it.
 */
export function problemVisibilityNotEnabled(requestId: string, instance?: string): Response {
  return problemResponse(
    403,
    "Forbidden",
    "Survey visibility is not enabled for this organization",
    requestId,
    {
      code: "visibility_not_enabled",
      instance,
    }
  );
}

/** ENG-3282: `restricted` refused while outbound connections depend on the survey; lists them. */
export function problemVisibilityBlocked(
  requestId: string,
  blockers: ReadonlyArray<Readonly<{ id: string; name: string; type: string }>>,
  instance?: string
): Response {
  return problemResponse(
    409,
    "Conflict",
    "Remove the connections that use this survey before restricting it",
    requestId,
    { code: "visibility_blocked_by_connections", details: { blockers }, instance }
  );
}

/**
 * A survey delete refused while non-archived creatives open the survey; lists them so the caller
 * can delete each one (pausing or closing a creative keeps its link).
 */
export function problemSurveyHasLinkedCreatives(
  requestId: string,
  creatives: ReadonlyArray<Readonly<{ id: string; name: string }>>,
  instance?: string
): Response {
  return problemResponse(
    409,
    "Conflict",
    "Delete the creatives that open this survey before deleting it",
    requestId,
    {
      code: "survey_has_linked_creatives",
      details: { creatives: creatives.map(({ id, name }) => ({ id, name })) },
      instance,
    }
  );
}

/** ENG-3282: `restricted` refused because the survey has no owner (Decision log #3). */
export function problemVisibilityChangeNotAllowed(requestId: string, instance?: string): Response {
  return problemResponse(
    422,
    "Unprocessable Content",
    "A survey without an author can't be restricted. Duplicate it to get a restricted copy you own.",
    requestId,
    { code: "visibility_change_not_allowed", instance }
  );
}

/**
 * ENG-3282: a grant was stored but the graph did not acknowledge it in-request. The survey stays
 * restricted until the outbox delivers it; retrying is safe.
 */
export function problemProjectionPending(requestId: string, instance?: string): Response {
  return problemResponse(
    503,
    "Service Unavailable",
    "The change is stored and will take effect shortly; the survey stays restricted until it does",
    requestId,
    { code: "projection_pending", headers: { "Retry-After": "5" }, instance }
  );
}

/**
 * ENG-3282: the workspace already holds `SURVEY_WORKSPACE_LIMIT` surveys. `details` carries the limit
 * and the current count so a client can say how many to archive or delete without a second call.
 */
export function problemWorkspaceSurveyLimit(
  requestId: string,
  limit: number,
  count: number,
  instance?: string
): Response {
  return problemResponse(
    422,
    "Unprocessable Content",
    "This workspace has reached its survey limit",
    requestId,
    {
      code: "workspace_survey_limit_reached",
      details: { count, limit },
      instance,
    }
  );
}

/**
 * ENG-6590: a chart still on a dashboard cannot be deleted — deleting it would break every dashboard that
 * shows it. `details.dashboards` names them, so the caller can take the chart off first. There is no force
 * option.
 */
export function problemChartInUse(
  requestId: string,
  dashboards: { id: string; name: string }[],
  instance?: string
): Response {
  return problemResponse(
    409,
    "Conflict",
    `This chart is on ${dashboards.length} dashboard(s), so it was not deleted. Remove it from them first.`,
    requestId,
    { code: "chart_in_use", instance, details: { dashboards } }
  );
}

export function problemConflict(
  requestId: string,
  detail: string,
  instance?: string,
  // ENG-3069: `details` carries the machine-readable half of an optimistic-concurrency failure
  // (`expectedUpdatedAt` / `currentUpdatedAt`). Without it a client can only re-read and guess,
  // and the human `detail` string is the wrong place for a value a retry has to compare.
  options?: { details?: Record<string, unknown> }
): Response {
  return problemResponse(409, "Conflict", detail, requestId, {
    code: "conflict",
    instance,
    ...(options?.details && { details: options.details }),
  });
}

export function problemBadGateway(
  requestId: string,
  detail: string,
  instance?: string,
  code: V3ProblemCode = "bad_gateway"
): Response {
  return problemResponse(502, "Bad Gateway", detail, requestId, {
    code,
    instance,
  });
}

/**
 * 503 for a capability that is not enabled on this deployment (as opposed to a transient outage, which
 * is a 502). `detail` should say what to configure — a bare "unavailable" is not actionable.
 */
export function problemServiceUnavailable(requestId: string, detail: string, instance?: string): Response {
  return problemResponse(503, "Service Unavailable", detail, requestId, {
    code: "service_unavailable",
    instance,
  });
}

/**
 * 503 for a route that is at its concurrency limit on this server (`concurrency` in
 * `withV3ApiWrapper`). Unlike `problemServiceUnavailable`, the capability is enabled and the caller
 * did nothing wrong: the same request succeeds once a slot frees up, and `Retry-After` says when to try.
 *
 * `capacity_reached` is an internal code. A public route that adopts the limit has to publish it in
 * `Problem.yml` first (`problem-codes.test.ts` keeps the two vocabularies apart).
 */
export function problemCapacityReached(
  requestId: string,
  retryAfterSeconds: number,
  instance?: string
): Response {
  return problemResponse(
    503,
    "Service Unavailable",
    `This server is busy with other requests like this one. Try again in ${retryAfterSeconds} seconds.`,
    requestId,
    { code: "capacity_reached", instance, headers: { "Retry-After": String(retryAfterSeconds) } }
  );
}

/**
 * 429 for a caller that already runs as many requests on a route as it may at once (`maxPerKey` in
 * `withV3ApiWrapper`'s `concurrency`). Its own code, not the rate limit's `too_many_requests`: the fix is
 * to wait for the caller's own request to finish, not to slow down, and a client says so.
 *
 * `concurrency_limit_reached` is an internal code, published the same way as `capacity_reached`.
 */
export function problemConcurrencyLimitReached(
  requestId: string,
  retryAfterSeconds: number,
  instance?: string
): Response {
  return problemResponse(
    429,
    "Too Many Requests",
    "You already have as many of these requests running as this route allows. Wait for one to finish.",
    requestId,
    { code: "concurrency_limit_reached", instance, headers: { "Retry-After": String(retryAfterSeconds) } }
  );
}

/**
 * 404 with resource details. Do not use for auth-sensitive or existence-sensitive resources:
 * the body includes resource_type and resource_id, which can leak existence to unauthenticated or unauthorized callers.
 * Prefer problemForbidden with a generic message for those cases.
 */
export function problemNotFound(
  requestId: string,
  resourceType: string,
  resourceId: string | null,
  instance?: string
): Response {
  return problemResponse(404, "Not Found", `${resourceType} not found`, requestId, {
    code: "not_found",
    details: { resource_type: resourceType, resource_id: resourceId },
    instance,
  });
}

export function problemInternalError(
  requestId: string,
  detail: string = "An unexpected error occurred.",
  instance?: string
): Response {
  return problemResponse(500, "Internal Server Error", detail, requestId, {
    code: "internal_server_error",
    instance,
  });
}

export function problemTooManyRequests(
  requestId: string,
  detail: string,
  retryAfter?: number,
  instance?: string
): Response {
  const headers: Record<string, string> = {};
  if (retryAfter !== undefined) {
    headers["Retry-After"] = String(retryAfter);
  }
  return problemResponse(429, "Too Many Requests", detail, requestId, {
    code: "too_many_requests",
    instance,
    headers,
  });
}

export function successListResponse<T, TMeta extends Record<string, unknown>>(
  data: T[],
  meta: TMeta,
  options?: { requestId?: string; cache?: string }
): Response {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    "Cache-Control": options?.cache ?? CACHE_NO_STORE,
  };
  if (options?.requestId) {
    headers["X-Request-Id"] = options.requestId;
  }
  return Response.json({ data, meta }, { status: 200, headers });
}

/**
 * Top-level members a success body may carry beside `data` — additive, never a replacement for it. The
 * custom CSS writes use it for `warnings` (ENG-3641), which describe the request rather than the
 * resource, so they stay out of `data` and a PATCH that round-trips `data` never sends them back.
 */
type TSuccessExtensions = { warnings?: unknown[]; meta?: Record<string, unknown> };

export function successResponse<T>(
  data: T,
  options?: { requestId?: string; cache?: string; status?: number; extensions?: TSuccessExtensions }
): Response {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    "Cache-Control": options?.cache ?? CACHE_NO_STORE,
  };

  if (options?.requestId) {
    headers["X-Request-Id"] = options.requestId;
  }

  return Response.json(
    {
      data,
      ...options?.extensions,
    },
    {
      status: options?.status ?? 200,
      headers,
    }
  );
}

export function createdResponse<T>(
  data: T,
  options: { location: string; requestId?: string; cache?: string; extensions?: TSuccessExtensions }
): Response {
  const headers: Record<string, string> = {
    "Content-Type": "application/json",
    "Cache-Control": options.cache ?? CACHE_NO_STORE,
    Location: options.location,
  };

  if (options.requestId) {
    headers["X-Request-Id"] = options.requestId;
  }

  return Response.json(
    {
      data,
      ...options.extensions,
    },
    {
      status: 201,
      headers,
    }
  );
}

export function noContentResponse(options?: { requestId?: string; cache?: string }): Response {
  const headers: Record<string, string> = {
    "Cache-Control": options?.cache ?? CACHE_NO_STORE,
  };

  if (options?.requestId) {
    headers["X-Request-Id"] = options.requestId;
  }

  return new Response(null, {
    status: 204,
    headers,
  });
}

import "server-only";
import type { logger } from "@formbricks/logger";
import {
  AuthorizationError,
  DatabaseError,
  OperationNotAllowedError,
  ResourceNotFoundError,
  TooManyRequestsError,
  UniqueConstraintError,
} from "@formbricks/types/errors";
import {
  problemConflict,
  problemForbidden,
  problemInternalError,
  problemTooManyRequests,
} from "@/app/api/v3/lib/response";

/**
 * The one place that turns an unexpected throw into a v3 problem response.
 *
 * This tail — missing resource, database failure, anything else — used to be written out at every v3
 * error boundary, nine times, with the branches in different orders and the log fields under different
 * keys. Duplicating it meant each surface separately re-decided what a thrown error may disclose, which
 * is the decision least safe to re-make by hand.
 *
 * Callers own the branches above this one. A surface that can distinguish its own domain failures maps
 * those first and delegates the tail here — see `mapV3SurveyCreateError` and
 * `mapV3SurveyGenerateError`. A surface with nothing to add calls this directly.
 */

/**
 * The part of the request-bound logger this mapper uses. Narrower than the logger itself on purpose: it
 * only ever writes one line, so callers are not asked for a whole pino instance and a test can supply a
 * plain pair of spies without casting.
 */
type TV3ErrorLogger = Pick<ReturnType<typeof logger.withContext>, "warn" | "error">;

type TV3ErrorContext = {
  log: TV3ErrorLogger;
  requestId: string;
  instance: string;
  /**
   * Dotted operation label ("surveys.archive"), for tracing which operation failed.
   *
   * A structured log field rather than part of the message, so the messages here stay a small closed set
   * that can be grouped and alerted on. It replaces the six bespoke message strings the copies used
   * ("V3 surveys list unexpected error", "V3 survey get unexpected error", …), which could not be
   * queried as one thing.
   */
  operation?: string;
  /**
   * Extra log fields, for context an operation only resolves partway through and so cannot put on its
   * request-bound logger — the survey patch path's `workspaceId` is the one case today.
   *
   * Merged into the log entry, never into the response body.
   */
  logFields?: Record<string, unknown>;
};

/**
 * Map an unexpected throw to a controlled v3 problem response, logging it exactly once.
 *
 * Two rules hold across every branch. A 5xx never echoes the error's message: `DatabaseError` wraps the
 * raw Prisma text by codebase convention, which carries table, column and constraint names. And a 4xx
 * only ever carries a fixed string — an `AuthorizationError`'s or `OperationNotAllowedError`'s message
 * is written for a developer, and `@/lib/ai/service` even throws the latter with a machine code as its
 * message. A surface whose conflict or refusal has something specific and safe to say maps that error
 * itself, above this call, the way the survey mappers do for their own domain errors.
 *
 * The thrown value is logged under the key `err`, not `error`: `@formbricks/logger` registers
 * pino's `stdSerializers.err` for that key only, so any other key logs the enumerable own properties
 * and silently drops `message` and `stack` — which is most of what a 500's log is for.
 *
 * `ValidationError` and `InvalidInputError` are deliberately absent. Both are 400-ish by `statusCode`,
 * but neither is safe to map centrally: `createSurvey` throws `ValidationError` from work it does
 * *after* its transaction commits, where a 4xx would wrongly tell the caller nothing was written
 * (ENG-2587), and `InvalidInputError` is only the caller's fault where the operation has established
 * that the input is theirs. Both stay with the surfaces that can tell the difference, above this call.
 */
export function mapV3ThrownError(err: unknown, ctx: TV3ErrorContext): Response {
  const { log, requestId, instance, operation, logFields } = ctx;
  const context = { ...logFields, ...(operation ? { operation } : {}) };

  /**
   * 403, not 404: a resource the caller cannot see must not be distinguishable from one that does not
   * exist, or the response becomes an existence oracle. The id is left out of the body for the same
   * reason — it goes to the log instead, correlated by `requestId`, which is the only place it is safe
   * to say which resource was missing.
   */
  if (err instanceof ResourceNotFoundError) {
    log.warn(
      {
        ...context,
        statusCode: 403,
        errorCode: err.name,
        resourceId: err.resourceId,
        resourceType: err.resourceType,
      },
      "V3 resource not found"
    );
    return problemForbidden(requestId, undefined, instance);
  }

  if (err instanceof AuthorizationError || err instanceof OperationNotAllowedError) {
    log.warn({ ...context, statusCode: 403, errorCode: err.name }, "V3 operation not permitted");
    return problemForbidden(requestId, undefined, instance);
  }

  // Raised by a dependency the operation called, or by the custom CSS budget a survey or workspace write
  // spends when it processes CSS — not by this API's own request limit, which answers in `withV3ApiWrapper` before
  // the handler runs. Passing `retryAfter` through is what stops an agent retry-looping blind.
  if (err instanceof TooManyRequestsError) {
    log.warn({ ...context, statusCode: 429, errorCode: err.name }, "V3 upstream rate limit");
    return problemTooManyRequests(
      requestId,
      "The service is rate limiting requests. Try again shortly.",
      err.retryAfter,
      instance
    );
  }

  /**
   * A 500 here would be actively harmful, not merely imprecise: it invites a retry of a request that
   * can never succeed. `ForeignKeyConstraintError` is deliberately not mapped alongside it despite
   * declaring the same 409 — a dangling reference is a fault in the caller's input, better answered as
   * a 422 naming the offending field, which only the surface that knows the field can build.
   */
  if (err instanceof UniqueConstraintError) {
    log.warn({ ...context, statusCode: 409, errorCode: err.name }, "V3 uniqueness conflict");
    return problemConflict(requestId, "The request conflicts with an existing resource.", instance);
  }

  if (err instanceof DatabaseError) {
    log.error({ ...context, err, statusCode: 500 }, "V3 database error");
    return problemInternalError(requestId, undefined, instance);
  }

  log.error({ ...context, err, statusCode: 500 }, "V3 unexpected error");
  return problemInternalError(requestId, undefined, instance);
}

